{
  "probability": 0.97,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Anchored on the reference class of IOM Missing Migrants Project's Central Mediterranean death toll with an anchor prior around 0.75.",
    "Early 2026 pace shows at least 606 deaths or missing by February, plus a high 2025 baseline (~2,100 Mediterranean deaths), signaling high risk of reaching 1,000+ by May 2026.",
    "Calibrated Bayesian update yields a posterior around 97% for recording at least 1,000 deaths before May 2026, though weather, SAR capacity, and reporting gaps introduce uncertainty."
  ],
  "confidence": "high",
  "narrative": "The observed pace through February 2026, combined with a historically high Mediterranean toll in 2025, implies a high likelihood that the Missing Migrants Project will record at least 1,000 deaths before May 2026. While data lags and weather/SAR dynamics could alter the path, the posterior probability remains strongly favorable.",
  "justification": {
    "anchor": {
      "probability": 0.75,
      "basis": "Starting point anchored to the reference class: IOM Missing Migrants Project's Mediterranean mortality in the Central Mediterranean route, with early-2026 signals informing a strong probability prior"
    },
    "factor_updates": [
      {
        "factor": "Early-2026 fatality pace on the Mediterranean",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "As of late February 2026, ~606 deaths/missing; if this pace persists, 1,000+ by May is plausible."
      },
      {
        "factor": "High baseline annual toll on the Central Mediterranean route",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "2025 toll ~2,100; high baseline indicates continued elevated risk."
      },
      {
        "factor": "Weather/storm risk and favorable crossing conditions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Severe weather increases fatalities; variable conditions create upside risk."
      },
      {
        "factor": "Reporting gaps and potential revisions",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Counts may be revised upward; undercounts possible."
      },
      {
        "factor": "Policy/SAR dynamics (search-and-rescue and governance)",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Uncertain directional impact depending on rescue capacity and governance."
      }
    ],
    "synthesis_rationale": "Starting from a conservative anchor, strong up-dates from current pace and high baseline risk drive the posterior toward 0.97. Calibration accounts for data lags and potential revisions; correlated factors are treated as a coherent upward pressure, with residual uncertainty from weather/SAR dynamics."
  }
}

{
  "probability": 0.97,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Early-2026 pace: by late Feb 2026, at least 606 deaths/missing, suggesting a pace that could reach 1,000 by May if sustained.",
    "High 2025 baseline (~2,100 Mediterranean deaths) reinforces the risk that 2026 could exceed 1,000 before May.",
    "Moderating uncertainty from weather, SAR capacity, and reporting gaps means ongoing revision risk; overall probability remains high."
  ],
  "confidence": "high",
  "narrative": "Combined evidence from an unusually high early-2026 death pace and a high 2025 baseline implies a high probability that IOM Missing Migrants Project will record at least 1,000 Mediterranean deaths before May 2026. Bayesian updates from multiple correlated factors push the posterior toward ~0.97, though weather and reporting revisions introduce some uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.90,
      "basis": "Reference class: IOM Missing Migrants Project Mediterranean deaths; anchor chosen near the mid-to-high end of recent annual tolls to reflect a high baseline risk and the observed early-2026 pace."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 pace on the Mediterranean",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "By February 2026, at least 606 deaths/missing; if the pace continues as in Jan-Feb, the 1,000 threshold by May is plausible."
      },
      {
        "factor": "High 2025 Mediterranean death toll baseline",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "2025 toll around 2,100; high baseline makes 1,000 by May more likely even with some variation."
      },
      {
        "factor": "Weather/SAR capacity and reporting gaps",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Adverse weather and limited SAR can raise fatalities and slow reporting, increasing observed counts and potential revisions upward."
      },
      {
        "factor": "Data lag and potential revisions",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Counts may be revised upward as verifications complete; this creates upside risk to near-term totals."
      },
      {
        "factor": "Policy/SAR dynamics",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Changes in SAR policy could alter outcomes; current data does not reliably indicate a clear directional impulse."
      },
      {
        "factor": "Mitigation via improved SAR or safer conditions",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Potential reductions if SAR improves or conditions are safer."
      }
    ],
    "synthesis_rationale": "Weighing several strong, correlated drivers toward higher fatalities (pace, baseline, weather/reports) while noting a weaker mitigating factor (SAR improvements), the posterior probability concentrates near the upper end. Correlations among pace, baseline, and reporting mean the update effects are not strictly additive; the calibrated posterior at 0.97 reflects the aggregation of evidence with an explicit uncertainty range."
  }
}

